class NumMatrix {
  constructor(matrix) {
    const rows = matrix.length;
    const cols = matrix[0].length;
    this.prefix = Array.from({ length: rows + 1 }, () =>
      new Array(cols + 1).fill(0)
    );

    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        this.prefix[r + 1][c + 1] =
          matrix[r][c] +
          this.prefix[r][c + 1] +
          this.prefix[r + 1][c] -
          this.prefix[r][c];
      }
    }
  }

  sumRegion(r1, c1, r2, c2) {
    return this.prefix[r2 + 1][c2 + 1]
         - this.prefix[r1][c2 + 1]
         - this.prefix[r2 + 1][c1]
         + this.prefix[r1][c1];
  }
}
